(* [comment removed for export] *)
(* [comment removed for export] *)
Section Run.
Variables (R : bvmap 5 word) (M0 : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (cr : credit)
          (sp r fb cat n : Z) (s : PQM.mpst) (st : NEM.aest) (str : PM.vstr) (sm : PM.strm) (e eb : bool) (t : Z).
Let op : Z := fb + 32.
Let ois : Z := fb + 616.
Let oa : Z := fb + 432.
Let oec : Z := fb + 8.
Let ov : Z := fb + 536.
Let osk : Z := fb + 592.
(* [comment removed for export] *)
Abbreviation ae_at := (NEM.ae_at RSEGS AD AE L PMSP.T3 PMSP.T4 (qa_vp_adaptor AQ)).

Hypothesis HH0 : hi_heap HI (PNRN.mown s st ++ LBX) cr M0 (m_vmmaps model).
Hypothesis MOK : PMSP.model_ok model.
Hypothesis K0 : K [].
Hypothesis Rra : getr R (PMK.reg 1) = Z_to_bv 64 r.
Hypothesis RAok : L5.ra_ok r.
Hypothesis Rsp : getr R (PMK.reg 2) = Z_to_bv 64 sp.
Hypothesis Rgp : getr R (PMK.reg 3) = Z_to_bv 64 (pa_gp AD).
Hypothesis Rtp : getr R (PMK.reg 4) = Z_to_bv 64 (pa_tp AD).
Hypothesis STK0 : L5C.stk (hl_sptop L) M0 sp 30720.
Hypothesis F1 : sp <= fb.
Hypothesis F2 : fb + 928 <= hl_sptop L.
Hypothesis F3 : fb mod 16 = 0.
Hypothesis A10 : getr R (PMK.reg 10) = Z_to_bv 64 op.
Hypothesis A11 : getr R (PMK.reg 11) = Z_to_bv 64 oa.
Hypothesis A12 : getr R (PMK.reg 12) = Z_to_bv 64 t.
Hypothesis A13 : getr R (PMK.reg 13) = Z_to_bv 64 oec.
Hypothesis Ht : PQR.ba_type t.
Hypothesis PA0 : PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M0 op ois s.
Hypothesis AA0 : ae_at M0 oa ov osk st.
Hypothesis IA0 : PM.iss_at RSEGS AD PMSP.T3 M0 ois str sm.
Hypothesis VREF0 : L5.u64_at RSEGS M0 (op + 496) oa.
Hypothesis BASE0 : PMST.base_ok RSEGS AD M0.
Hypothesis ERR0 : PQST.err_ok RSEGS AD AQ M0 e.
Hypothesis GROW0 : PQM.mgrow_ok s.
Hypothesis AOK0 : NEM.ae_ok st.
Hypothesis CPL0 : PQM.cpl s (NEM.ae_a st).
Hypothesis ACCT0 : PQM.acct n s (NEM.ae_a st) sm.
Hypothesis ACCT4 : PQM.acct_d 4 n s (NEM.ae_a st) sm.
Hypothesis OACCT0 : NEM.oacct n s st sm.
Hypothesis OACCT8 : NEM.oacct_d 8 n s st sm.
Hypothesis EB0 : NEM.ebound st.
Hypothesis BAL0 : eb = false -> NEM.bal st.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis INV : PQR.minv_d 0 s.
Hypothesis EC0 : NEM.ec_state RSEGS AD M0 oec eb cat.
Hypothesis CRED : PMSP.credit_le (PM.credit_add (PNRN.pot_run L s st) PNRN.TSRES_ME) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (s' : PQM.mpst) (st' : NEM.aest)
            (sm' : PM.strm) (e' b' : bool) (cr' : credit),
        regs_preserved R R' ->
        PNRN.mrun_post_d RSEGS AD AQ AE L 0 PNRN.mprog_push R' M' fb s s' st st' str sm sm' e e' eb b' cat n ->
        L5C.hpres L LBX sp (PMSP.pm_scr 9) (PNRN.W_mrun AD AQ AE fb) M0 M' ->
        PMSP.credit_keep cr cr' (PNRN.pot_run L s st) (PNRN.pot_run L s' st') ->
        model_but_vm model model' -> hi_heap HI (PNRN.mown s' st' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

(* [comment removed for export] *)
Definition cm (M1 : word -> option byte) : Prop :=
  PMK.ek L LBX sp 30720 (PNRN.W_mrun AD AQ AE fb) M0 M1 /\ PMK.dk L LBX sp 30720 M0 M1 /\ L5C.stk (hl_sptop L) M1 sp 30720.
(* [comment removed for export] *)
Definition saved (M1 : word -> option byte) : Prop :=
  L5.u64_at RSEGS M1 (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS M1 (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
  /\ L5.u64_at RSEGS M1 (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS M1 (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
  /\ L5.u64_at RSEGS M1 (sp - 40) (bv_unsigned (getr R (PMK.reg 19))) /\ L5.u64_at RSEGS M1 (sp - 48) (bv_unsigned (getr R (PMK.reg 20)))
  /\ L5.u64_at RSEGS M1 (sp - 56) (bv_unsigned (getr R (PMK.reg 21))) /\ L5.u64_at RSEGS M1 (sp - 64) (bv_unsigned (getr R (PMK.reg 22))).

