Lemma VISC (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s2 : PQM.mpst) (sm1 : PM.strm) (e1 : bool)
      (cr1 : credit) (len gsb : Z) :
  getr R1 (PMK.reg 1) = Z_to_bv 64 0x467b4 -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R1 (PMK.reg 8) = Z_to_bv 64 op ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 oec -> getr R1 (PMK.reg 18) = Z_to_bv 64 oa -> getr R1 (PMK.reg 10) = Z_to_bv 64 oa ->
  getr R1 (PMK.reg 11) = Z_to_bv 64 len -> getr R1 (PMK.reg 14) = Z_to_bv 64 oec -> 0 <= len < 2 ^ 64 ->
  PNRN.gs_class t len gsb -> PM.unread (PQM.p_src s2) sm1 <= PM.unread (PQM.p_src s) sm - gsb ->
  (forall x, In x [3; 4; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois s2 ->
  ae_at M1 oa ov osk st ->
  others M1 sm1 e1 -> (e = true -> e1 = true) -> PQM.mgrow_ok s2 -> PQR.minv_d 0 s2 -> PQR.mpush1 s s2 ->
  PMSP.src_step (PQM.p_src s) (PQM.p_src s2) sm sm1 ->
  saved M1 -> cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s2 st) ->
  model_but_vm model model1 -> hi_heap HI (PNRN.mown s2 st ++ LBX) cr1 M1 (m_vmmaps model1) ->
  PNV.v_begin_array_spec RSEGS AD AQ AE L HI ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x39868 M1 model1) K.
Proof.
