(* [comment removed for export] *)
Definition gcls (s1 : PQM.mpst) (sm1 : PM.strm) (len : Z) : Prop :=
  exists gsb, PNRN.gs_class t len gsb /\ PM.unread (PQM.p_src s1) sm1 <= PM.unread (PQM.p_src s) sm - gsb.
Definition gsok (M1 : word -> option byte) (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (len : Z) : Prop :=
  PNRN.mrun_pre RSEGS AD AQ AE L M1 fb s1 st str sm1 e1 eb cat n /\ (e = true -> e1 = true) /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s1) sm sm1
  /\ NEM.ec_state RSEGS AD M1 oec eb cat /\ PQR.minv_d 1 s1 /\ PQM.p_stk s1 = PQM.p_stk s /\ gcls s1 sm1 len.

