Definition sdep (s1 : PQM.mpst) (d : Z) : PQM.mpst :=
  PQM.MPST (PQM.p_more s1) (PQM.p_done s1) d (PQM.p_src s1) (PQM.p_tb s1) (PQM.p_tg s1) (PQM.p_bb s1) (PQM.p_bg s1) (PQM.p_sb s1)
