Lemma AFTER_GS (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (st1 : NEM.aest)
      (sm1 : PM.strm) (e1 b1 : bool) (cr1 : credit) :
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R1 (PMK.reg 8) = Z_to_bv 64 op ->
  getr R1 (PMK.reg 9) = Z_to_bv 64 oec -> getr R1 (PMK.reg 18) = Z_to_bv 64 oa ->
  (forall x, In x [3; 4; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  PNRN.gs_post_d RSEGS AD AQ AE L 1 t R1 M1 fb (sdep s (PQM.p_depth s + 1)) s1 st st1 str sm sm1 e e1 eb b1 cat n ->
  Z.of_nat (length (PQM.p_stk s)) <= PQM.MAX_DEPTH ->
  saved M1 -> cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st1) ->
  model_but_vm model model1 -> hi_heap HI (PNRN.mown s1 st1 ++ LBX) cr1 M1 (m_vmmaps model1) ->
  PMS.opnew_spec L HI -> PMS.opdel_spec L HI -> PNV.v_begin_array_spec RSEGS AD AQ AE L HI ->
