Definition HR (R1 : bvmap 5 word) : Prop :=
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) /\ getr R1 (PMK.reg 8) = Z_to_bv 64 (fb + 8) /\ getr R1 (PMK.reg 9) = Z_to_bv 64 (fb + 32)
  /\ getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 432) /\ getr R1 (PMK.reg 19) = Z_to_bv 64 4 /\ getr R1 (PMK.reg 20) = Z_to_bv 64 1
  /\ getr R1 (PMK.reg 21) = Z_to_bv 64 24 /\ getr R1 (PMK.reg 22) = Z_to_bv 64 256 /\ getr R1 (PMK.reg 23) = Z_to_bv 64 0x13944
  /\ getr R1 (PMK.reg 24) = Z_to_bv 64 3
  /\ (forall x, In x [3; 4; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x)).

