(* [comment removed for export] *)
Definition AH (R1 : bvmap 5 word) (M1 : word -> option byte) (s1 : PQM.mpst) (st1 : NEM.aest) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (model1 : Model) : Prop :=
  HR R1 /\ LS M1 s1 st1 sm1 e1 cr1 model1 /\ PQR.minv_d 0 s1
  /\ (exists b1 : bool, NEM.ec_state RSEGS AD M1 oec b1 cat /\ (b1 = false -> NEM.bal st1)).

(* [comment removed for export] *)
Definition HEADK (mu : Z) : Prop :=
  forall (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (st1 : NEM.aest) (sm1 : PM.strm) (e1 : bool) (cr1 : credit),
    AH R1 M1 s1 st1 sm1 e1 cr1 model1 -> PQR.mmu s1 sm1 < mu -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x455fc M1 model1) K.

