Lemma POST_TOP (fx1 fx2 : FPState) (R1 R2 : bvmap 5 word) (M1 M2 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (st1 : NEM.aest)
      (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (pre : list PQM.mstate) (top top' : PQM.mstate) :
  PNRN.read_item_spec RSEGS AD AQ AE L HI -> HEADK (PQR.mmu s1 sm1) ->
  AH R1 M1 s1 st1 sm1 e1 cr1 model1 -> PQM.p_stk s1 = pre ++ [top] ->
  PQM.mstate_ok top' -> (pre = [] -> PQM.mode_bottom (PQM.ms_mode top')) -> (pre <> [] -> PQM.mode_cont (PQM.ms_mode top')) ->
  msteps RSEGS (@mkst fx1 R1 (Z_to_bv 64 0x455fc) M1 (seg_rom RSEGS)) (@mkst fx2 R2 (Z_to_bv 64 0x457a8) M2 (seg_rom RSEGS)) -> mem_grows M1 M2 ->
