Lemma LOOP : PNRN.read_item_spec RSEGS AD AQ AE L HI -> PNV.v_end_array_spec RSEGS AD AQ AE L HI -> PNV.v_end_object_spec RSEGS AD AQ AE L HI -> PNV.v_flush_spec RSEGS AD AQ AE L HI ->
  forall (mu : Z), 0 <= mu -> forall (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (st1 : NEM.aest)
      (sm1 : PM.strm) (e1 : bool) (cr1 : credit),
  AH R1 M1 s1 st1 sm1 e1 cr1 model1 -> PQR.mmu s1 sm1 = mu ->
