(* [comment removed for export] *)
Theorem v_string_none (h : Z) : h = 6 \/ h = 7 -> NESK.sp_mode P ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (cr : credit) (sp r ov osk oec cat p d n : Z) (bs : list Z) (en : enc) (k : NESK.sink) (b e : bool),
    hi_heap HI (NECS.eown en k ++ LBX) cr M (m_vmmaps model) -> PMSP.model_ok model -> K [] -> PMSP.entry CAD L R M sp r h ->
    getr R 10%bv = Z_to_bv 64 ov -> getr R 11%bv = Z_to_bv 64 p -> getr R 12%bv = Z_to_bv 64 0 -> sp <= p -> p + 16 <= ov ->
    NECS.view_ok RSEGS M sp ov LBX p d n -> L5.bytes_at RSEGS M d bs -> Z.of_nat (length bs) = n -> utf8_valid bs = true -> bytes_ok bs ->
    sp <= ov -> ov + 56 <= hl_sptop L -> ov mod 8 = 0 -> sp <= osk -> osk + 24 <= hl_sptop L -> osk mod 8 = 0 ->
    sp <= oec -> oec + 16 <= hl_sptop L -> oec mod 8 = 0 -> oec + 16 <= ov -> ov + 56 <= osk ->
    enc_at M ov osk en -> sink_atP M osk k -> ec_state M oec b cat -> PMST.base_ok RSEGS CAD M -> PQST.err_ok RSEGS CAD AQ M e ->
    NESK.sk_z k + hdr_str n + n <= NESK.SMZ -> PMSP.credit_le (NECS.pot_enc L P en k) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (k' : NESK.sink) (cr' : credit),
        regs_preserved R R' ->
        enc_at M' ov osk en -> sink_atP M' osk k' -> ec_state M' oec b cat -> PMST.base_ok RSEGS CAD M' -> PQST.err_ok RSEGS CAD AQ M' e ->
        NESK.sk_z k' = NESK.sk_z k + hdr_str n + n ->
        L5C.hpres L LBX sp (PMSP.pm_scr h) (NECS.W_enc CAD ov osk oec) M M' ->
        PMSP.credit_keep cr cr' (NECS.pot_enc L P en k) (NECS.pot_enc L P en k') ->
        model_but_vm model model' -> hi_heap HI (NECS.eown en k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K) ->
