Section Glue.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LM : PQH.layoutM L.

(* [comment removed for export] *)
Record harness_deps : Prop := HDEPS {
  hd_str_ctor : PMS.str_ctor_spec L HI;
  hd_iss_ctor : PMS.iss_ctor_spec L HI;
  hd_reader_ctor : PQRH.reader_ctor_spec RSEGS AD AQ L HI;
  hd_syscat : PMS.syscat_spec L HI;
  hd_reset : PQR.reset_spec RSEGS AD AQ L HI;
  hd_parse : PNRN.parse_spec RSEGS AD AQ NemLayoutS.NEADDR_S L HI;
  hd_reader_dtor : PQRH.reader_dtor_spec RSEGS AD AQ L HI;
  hd_opdel : PMS.opdel_spec L HI;
  hd_locale_dtor : PMS.locale_dtor_spec L;
  hd_ios_dtor : PMS.ios_dtor_spec L HI
}.

Theorem harness_call_ok : harness_deps -> lib_call_ok (PQTS.TopLay L) SCFG HI PQTS.TopLS.
Proof.
  intros [STR ISS RDR SYS RST PARSE RDT OPD LDT IDT].
  unfold lib_call_ok. intros fx g LB cr sp ptr ra payload R M model K PRE HH Mh Ml Mm K0 KONT.
  unfold lib_cfg in *. cbn [ll_heap ll_entry PQTS.TopLay] in KONT |- *. rewrite (ly_segs L LY) in KONT |- *.
  set (n := Z.of_nat (length payload)).
  assert (Hn : 0 <= n < 2 ^ 26) by (pose proof (lp_len _ _ _ _ _ _ _ _ _ _ _ PRE) as X; unfold n; lia).
  assert (Hcr0 : PMSP.credit_le (PQTS.TOPK, PQTS.TOPB n) cr) by exact (lp_credit _ _ _ _ _ _ _ _ _ _ _ PRE).
  assert (Hgp : getr R (reg 3) = Z_to_bv 64 (pa_gp AD)) by (rewrite <- L5K.rl3; exact (lp_gp _ _ _ _ _ _ _ _ _ _ _ PRE)).
  assert (Htp : getr R (reg 4) = Z_to_bv 64 (pa_tp AD)).
  { rewrite <- L5K.rl4. pose proof (lp_tp _ _ _ _ _ _ _ _ _ _ _ PRE) as X. cbn [ll_heap PQTS.TopLay] in X. rewrite (ly_tp L LY) in X. exact X. }
  assert (Hsp0 : getr R (reg 2) = Z_to_bv 64 sp) by (rewrite <- L5K.rl2; exact (lp_sp _ _ _ _ _ _ _ _ _ _ _ PRE)).
  assert (Hra : L5.ra_ok ra) by exact (lp_ra_ok _ _ _ _ _ _ _ _ _ _ _ PRE).
  apply (PQH1.stage1 L HI LY HIok LM STR fx g LB cr sp ptr ra payload R M model K PRE HH Mh Ml Mm K0). fold n.
  intros fx1 R1 M1 model1 cr1 s H1.
  apply (PQH2.stage2 L HI LY HIok R M model sp ra n LB cr g Hn Hcr0 LM Hgp Htp ISS fx1 R1 M1 model1 cr1 s K H1 K0).
  clear fx1 R1 M1 model1 cr1 H1. intros fx2 R2 M2 model2 cr2 s2 sm H2.
  apply (PQH3.stage3 L HI LY HIok LM R M model sp ra n LB cr g Hn Hcr0 Hgp Htp RDR fx2 R2 M2 model2 cr2 s s2 sm K H2 K0).
  clear fx2 R2 M2 model2 cr2 H2. intros fx3 R3 M3 model3 cr3 qc b b' H3.
  apply (PQH4.stage4 L HI LY HIok R M model sp ra n LB cr g Hn Hgp Htp SYS RST fx3 R3 M3 model3 cr3 s s2 sm qc b b' K H3 K0).
  clear fx3 R3 M3 model3 H3. intros fx4 R4 M4 model4 H4.
  apply (PQH5.stage5 L HI LY HIok LM R M model sp ra n LB cr g Hn Hcr0 Hgp Htp PARSE fx4 R4 M4 model4 cr3 s s2 sm qc b b' K H4 K0).
  clear fx4 R4 M4 model4 cr3 H4. intros fx5 R5 M5 model5 cr5 sm5 p st be H5.
  apply (PQH6.stage6 L HI LY HIok R M model sp ra n LB cr g Hn Hgp Htp RDT fx5 R5 M5 model5 cr5 s s2 sm5 p st be K H5 K0).
  clear fx5 R5 M5 model5 H5. intros fx6 R6 M6 model6 H6.
  apply (PQH7.stage7 L HI LY HIok R M model sp ra n LB cr g Hn Hgp Htp OPD fx6 R6 M6 model6 cr5 s s2 sm5 (NEM.ae_e st) (NEM.ae_s st) be K H6 K0).
  clear fx6 R6 M6 model6 H6. intros fx7 R7 M7 model7 H7.
  apply (PQH8.stage8 L HI LY HIok R M model sp ra n LB cr g Hn Hcr0 Hgp Htp OPD LDT IDT fx7 R7 M7 model7 cr5 s s2 sm5 be K H7 K0).
  clear fx7 R7 M7 model7 H7. intros fx8 R8 M8 model8 H8.
  apply (PQH9.stage9 L HI LY HIok R M model sp ra n LB cr g Hn Hcr0 LM Hgp Htp Hsp0 Hra payload eq_refl OPD fx8 R8 M8 model8 cr5 s be K H8 K0).
  clear fx8 R8 M8 model8 H8. intros fx9 g9 R9 M9 model9 cr9 POST HH9 MB9.
  exact (KONT fx9 g9 R9 M9 model9 cr9 POST HH9 MB9).
Qed.

